svg.script:
(() => {
  const script = document.currentScript;
  const svg = script && script.ownerSVGElement;
  if (!svg || svg.dataset.cablePhysicsReady === 'true') return;
  const ownerWindow = svg.ownerDocument?.defaultView || window;
  const reduce = ownerWindow.matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const groups = new Map();
  svg.querySelectorAll('[data-swing]').forEach(node => {
    const key = node.getAttribute('data-swing');
    if (!groups.has(key)) groups.set(key, { key, paths: [] });
    groups.get(key).paths.push({ node, original: node.getAttribute('d') });
  });

  // Sample the actual artist-drawn curves. Every sample is a tiny flexible
  // joint; unlike cursor attraction, each joint has velocity and inertia.
  const cableGroups = [...groups.values()];
  const cables = [];
  let cableCursor = 0;
  function prepareNextCable() {
    if (cableCursor >= cableGroups.length) { installInteractions(); return; }
    const cable = cableGroups[cableCursor];
    const index = cableCursor++;
    const path = cable.paths[0].node;
    const length = path.getTotalLength();
    const count = length > 185 ? 22 : 10;
    const points = Array.from({ length: count }, (_, i) => {
      const t = i / (count - 1);
      const p = path.getPointAtLength(length * t);
      const p0 = path.getPointAtLength(length * Math.max(0, t - .012));
      const p1 = path.getPointAtLength(length * Math.min(1, t + .012));
      const vx = p1.x - p0.x, vy = p1.y - p0.y;
      const mag = Math.hypot(vx, vy) || 1;
      return { x: p.x, y: p.y, nx: -vy / mag, ny: vx / mag,
               displacement: 0, velocity: 0 };
    });
    cables.push({ ...cable, points, length, active: false, contact: false,
                  lastHit: -Infinity, index });
    setTimeout(prepareNextCable, 0);
  }

  // A smooth cubic path through the spring-mass joints. The endpoints
  // remain connected to the raccoon/server; no entire-path rotation.
  function renderCable(cable) {
    const ps = cable.points;
    const pts = ps.map((p, i) => {
      // Ease motion to zero near both attachments, avoiding sharp kinks.
      const fade = Math.sin(Math.PI * i / (ps.length - 1)) ** .7;
      return { x: p.x + p.nx * p.displacement * fade,
               y: p.y + p.ny * p.displacement * fade };
    });
    let d = `M${pts[0].x.toFixed(2)} ${pts[0].y.toFixed(2)}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[Math.max(0, i - 1)];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[Math.min(pts.length - 1, i + 2)];
      const x1 = p1.x + (p2.x - p0.x) / 6;
      const y1 = p1.y + (p2.y - p0.y) / 6;
      const x2 = p2.x - (p3.x - p1.x) / 6;
      const y2 = p2.y - (p3.y - p1.y) / 6;
      d += ` C${x1.toFixed(2)} ${y1.toFixed(2)} ${x2.toFixed(2)} ${y2.toFixed(2)} ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
    }
    for (const path of cable.paths) path.node.setAttribute('d', d);
  }

  // Scroll acts like a small change of gravity direction, NOT repeated
  // pushes that add up. The cable has mass, tension, and strong damping.
  let scrollLean = 0;
  let scrollGravity = 0;
  let lastScrollImpulse = 0;
  let raf = 0;
  let lastFrame = 0;
  function step(now) {
    // Time-corrected integration, capped after tabs sleep/wake.
    const dt = lastFrame ? clamp((now - lastFrame) / 16.667, .5, 1.65) : 1;
    lastFrame = now;
    // The temporary gravity tilt goes away after the scroll stops.
    if (now - lastScrollImpulse > 65) scrollLean *= Math.pow(.93, dt);
    if (now - lastScrollImpulse > 65) scrollGravity *= Math.pow(.91, dt);
    if (Math.abs(scrollLean) < .015) scrollLean = 0;
    if (Math.abs(scrollGravity) < .001) scrollGravity = 0;
    let moving = false;
    for (const cable of cables) {
      if (!cable.active) continue;
      const ps = cable.points;
      const accelerations = ps.map((p, i) => {
        if (i === 0 || i === ps.length - 1) return 0;
        const wave = ps[i - 1].displacement + ps[i + 1].displacement - 2 * p.displacement;
        // Normal projection creates a gentle sideways weight shift.
        // Neighbor coupling preserves the cable shape without rippling wildly.
        const hanging = Math.sin(Math.PI * i / (ps.length - 1));
        const leanTarget = p.nx * scrollLean * hanging;
        // Scroll speed briefly changes the vertical gravity on each joint.
        const gravityPull = p.ny * scrollGravity * hanging;
        return wave * .11 + (leanTarget - p.displacement) * .0195 + gravityPull;
      });
      let energy = 0;
      for (let i = 1; i < ps.length - 1; i++) {
        const p = ps[i];
        p.velocity = (p.velocity + accelerations[i] * dt) * Math.pow(.84, dt);
        p.displacement = clamp(p.displacement + p.velocity * dt, -16, 16);
        energy += p.velocity ** 2 + (p.displacement * .06) ** 2;
      }
      if (energy < .005 && Math.abs(scrollLean) < .12 && Math.abs(scrollGravity) < .01) {
        cable.active = false;
        for (const p of ps) { p.velocity = 0; p.displacement = 0; }
        for (const path of cable.paths) path.node.setAttribute('d', path.original);
      } else {
        renderCable(cable);
        moving = true;
      }
    }
    raf = moving ? requestAnimationFrame(step) : 0;
    if (!moving) lastFrame = 0;
  }

  function localPoint(event) {
    const ctm = svg.getScreenCTM();
    if (!ctm) return null;
    return new DOMPoint(event.clientX, event.clientY).matrixTransform(ctm.inverse());
  }
  function nearest(cable, x, y) {
    let best = { d: Infinity, i: -1 };
    const ps = cable.points;
    // Proximity is against the CURRENT moving vine, never an imaginary
    // magnetic point bound to the mouse's position.
    for (let i = 1; i < ps.length - 1; i++) {
      const p = ps[i];
      const fade = Math.sin(Math.PI * i / (ps.length - 1)) ** .7;
      const px = p.x + p.nx * p.displacement * fade;
      const py = p.y + p.ny * p.displacement * fade;
      const d = Math.hypot(px - x, py - y);
      if (d < best.d) best = { d, i };
    }
    return best;
  }
  function swish(cable, i, pointerDX, pointerDY, proximity, time) {
    const point = cable.points[i];
    const normalSpeed = pointerDX * point.nx + pointerDY * point.ny;
    if (Math.abs(normalSpeed) < 1.25) return;
    const direction = Math.sign(normalSpeed);
    // Quick pass = a stronger push; resting mouse = no force at all.
    const kick = direction * clamp(Math.abs(normalSpeed) * .165, .55, 2.9) * proximity;
    // A broader gentle swish makes the cable feel substantial, not whippy.
    const spread = cable.points.length > 12 ? 2.7 : 1.75;
    cable.points.forEach((p, j) => {
      if (j === 0 || j === cable.points.length - 1) return;
      const attenuation = Math.exp(-.5 * ((j - i) / spread) ** 2);
      p.velocity += kick * attenuation;
    });
    cable.lastHit = time;
    cable.active = true;
    if (!raf) raf = requestAnimationFrame(step);
  }

  let previous = null;
  function move(event) {
    if (reduce.matches || (event.pointerType && event.pointerType !== 'mouse' && event.pointerType !== 'pen')) return;
    const point = localPoint(event);
    if (!point) return;
    if (!previous) { previous = { x: point.x, y: point.y, time: performance.now() }; return; }
    const time = performance.now();
    const elapsed = time - previous.time;
    if (elapsed > 150) { previous = { x: point.x, y: point.y, time }; return; }
    const dx = point.x - previous.x;
    const dy = point.y - previous.y;
    // Ignore teleporting pointers rather than violently snapping a vine.
    if (Math.hypot(dx, dy) > 135) { previous = { x: point.x, y: point.y, time }; return; }
    const midX = (point.x + previous.x) / 2;
    const midY = (point.y + previous.y) / 2;
    for (const cable of cables) {
      const curr = nearest(cable, point.x, point.y);
      const prev = nearest(cable, previous.x, previous.y);
      const middle = nearest(cable, midX, midY);
      const hit = [curr, prev, middle].sort((a, b) => a.d - b.d)[0];
      // Exit hysteresis: a cable is contacted once per pass, never every
      // frame while the pointer lingers. No attraction or sticky dragging.
      if (Math.min(curr.d, middle.d) > 39) cable.contact = false;
      if (!cable.contact && hit.d < 26 && time - cable.lastHit > 180) {
        cable.contact = true;
        swish(cable, hit.i, clamp(dx, -35, 35), clamp(dy, -35, 35),
              clamp((36 - hit.d) / 28, .25, 1), time);
      }
    }
    previous = { x: point.x, y: point.y, time };
  }
  function resetPointer() {
    previous = null;
    for (const cable of cables) cable.contact = false;
    // Intentionally do NOT kill RAF: vines coast naturally after exit.
  }
  function readScrollY() {
    return ownerWindow.scrollY ?? ownerWindow.pageYOffset ?? svg.ownerDocument.documentElement?.scrollTop ?? 0;
  }
  function isVisible() {
    const rect = svg.getBoundingClientRect();
    const vh = ownerWindow.innerHeight || svg.ownerDocument.documentElement?.clientHeight || 0;
    const vw = ownerWindow.innerWidth || svg.ownerDocument.documentElement?.clientWidth || 0;
    return rect.bottom > 0 && rect.right > 0 && rect.top < vh && rect.left < vw;
  }
  let lastScrollY = readScrollY();
  let lastScrollTime = performance.now();
  function onScroll() {
    if (reduce.matches || !isVisible()) {
      lastScrollY = readScrollY();
      lastScrollTime = performance.now();
      scrollLean = 0;
      scrollGravity = 0;
      return;
    }
    const now = performance.now();
    const scrollY = readScrollY();
    const delta = scrollY - lastScrollY;
    const elapsed = Math.max(14, now - lastScrollTime);
    lastScrollY = scrollY;
    lastScrollTime = now;
    if (Math.abs(delta) < 1.5) return;
    const rawVelocity = clamp(delta / (elapsed / 16.667), -20, 20);
    // Replace an accumulated impulse with a bounded, smoothed tilt.
    scrollLean = clamp(scrollLean * .5 - rawVelocity * .29, -6.3, 6.3);
    // Downward scroll pulls the vines; upward scroll gives them a lift.
    scrollGravity = clamp(rawVelocity * .012, -0.24, 0.24);
    lastScrollImpulse = now;
    if (Math.abs(scrollLean) < .15 && Math.abs(scrollGravity) < .005) return;
    for (const cable of cables) cable.active = true;
    if (!raf) raf = requestAnimationFrame(step);
  }
  function installInteractions() {
  svg.dataset.cablePhysicsReady = 'true';
  svg.addEventListener('pointermove', move, { passive: true });
  svg.addEventListener('pointerleave', resetPointer, { passive: true });
  svg.addEventListener('pointercancel', resetPointer, { passive: true });
  ownerWindow.addEventListener('scroll', onScroll, { passive: true });
  ownerWindow.addEventListener('resize', () => { lastScrollY = readScrollY(); lastScrollTime = performance.now(); }, { passive: true });
  function resetMotion() {
    if (raf) cancelAnimationFrame(raf);
    raf = 0;
    lastFrame = 0;
    scrollLean = 0;
    scrollGravity = 0;
    for (const cable of cables) {
      cable.active = false;
      cable.contact = false;
      for (const p of cable.points) { p.displacement = 0; p.velocity = 0; }
      for (const path of cable.paths) path.node.setAttribute('d', path.original);
    }
    resetPointer();
  }
  // NAS hotswap bays really eject and reseat via click, Enter, or Space.
  svg.querySelectorAll('.nas-bay').forEach(bay => {
    const toggle = () => {
      const ejected = bay.getAttribute('data-ejected') !== 'true';
      bay.setAttribute('data-ejected', String(ejected));
      bay.setAttribute('aria-pressed', String(ejected));
      bay.setAttribute('aria-label', `${ejected ? 'Reseat' : 'Eject'} NAS drive bay ${bay.dataset.bay}`);
    };
    bay.addEventListener('click', toggle);
    bay.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle(); }
    });
  });
  reduce.addEventListener?.('change', () => { if (reduce.matches) resetMotion(); });
  svg.ownerDocument.addEventListener?.('visibilitychange', () => {
    if (svg.ownerDocument.hidden) { lastScrollY = readScrollY(); lastScrollTime = performance.now(); }
  });
  }
  const beginCableSetup = () => setTimeout(prepareNextCable, 0);
  if (svg.ownerDocument.readyState === 'complete') beginCableSetup();
  else ownerWindow.addEventListener('load', beginCableSetup, { once: true });
})();
